# PTX source for fp16 matrix multiplication (C = A * B^T)
PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

.visible .entry mm_kernel(
    .param .u64 A_ptr,
    .param .u64 B_ptr,
    .param .u64 C_ptr,
    .param .u32 M,
    .param .u32 N,
    .param .u32 K
)
{
    // Load parameters
    .reg .u64 a_ptr, b_ptr, c_ptr;
    .reg .u32 m, n, k;
    ld.param.u64 a_ptr, [A_ptr];
    ld.param.u64 b_ptr, [B_ptr];
    ld.param.u64 c_ptr, [C_ptr];
    ld.param.u32 m, [M];
    ld.param.u32 n, [N];
    ld.param.u32 k, [K];

    // Thread indices
    .reg .u32 tx, ty, bx, by;
    mov.u32 tx, %tid.x;
    mov.u32 ty, %tid.y;
    mov.u32 bx, %ctaid.x;
    mov.u32 by, %ctaid.y;

    // Global row & column
    .reg .u32 row, col;
    mad.lo.u32 row, by, %ntid.y, ty;   // row = by * blockDim.y + ty
    mad.lo.u32 col, bx, %ntid.x, tx;   // col = bx * blockDim.x + tx

    // Bounds check
    .pred p_out;
    setp.ge.u32 p_out, row, m;
    @p_out bra DONE;
    setp.ge.u32 p_out, col, n;
    @p_out bra DONE;

    // Compute base addresses (in bytes) for this row of A and this row of B (since B is stored as N x K)
    .reg .u64 base_a, base_b;
    .reg .u64 tmp64;
    mul.wide.u32 tmp64, row, k;          // row * K
    mul.wide.u32 base_a, tmp64, 2;       // * sizeof(fp16)

    mul.wide.u32 tmp64, col, k;          // col * K
    mul.wide.u32 base_b, tmp64, 2;       // * sizeof(fp16)

    // Accumulator in fp32
    .reg .f32 sum;
    mov.f32 sum, 0f0;

    // Loop over K dimension
    .reg .u32 kk;
    mov.u32 kk, 0;

LOOP:
    setp.ge.u32 p_out, kk, k;
    @p_out bra END_LOOP;

    // Load A[row, kk]
    .reg .u64 addr_a;
    mul.wide.u32 tmp64, kk, 2;           // kk * sizeof(fp16)
    add.u64 addr_a, base_a, tmp64;
    .reg .f16 a_f16;
    ld.global.f16 a_f16, [a_ptr + addr_a];

    // Load B[col, kk] (B is stored row‑major as N×K)
    .reg .u64 addr_b;
    add.u64 addr_b, base_b, tmp64;
    .reg .f16 b_f16;
    ld.global.f16 b_f16, [b_ptr + addr_b];

    // Convert to fp32 and FMA
    .reg .f32 a_f32, b_f32;
    cvt.f32.f16 a_f32, a_f16;
    cvt.f32.f16 b_f32, b_f16;
    fma.rn.f32 sum, a_f32, b_f32, sum;

    // kk++
    add.u32 kk, kk, 1;
    bra LOOP;

END_LOOP:
    // Convert result to fp16 and store
    .reg .f16 sum_f16;
    cvt.f16.f32 sum_f16, sum;

    // C offset = row * N + col
    .reg .u64 c_offset;
    mul.wide.u32 tmp64, row, n;          // row * N
    add.u64 c_offset, tmp64, col;        // row*N + col
    mul.wide.u32 c_offset, c_offset, 2;  // * sizeof(fp16)

    st.global.f16 [c_ptr + c_offset], sum_f16;

DONE:
    ret;
}
'''

# ----------------------------------------------------------------------
# Model wrapper that loads and launches the PTX kernel
# ----------------------------------------------------------------------
class ModelNew:
    def __init__(self):
        # Load the PTX module using the harness API
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, A, B):
        """
        A : torch.Tensor of shape (M, K), dtype=torch.float16, device='cuda'
        B : torch.Tensor of shape (N, K), dtype=torch.float16, device='cuda'
        Returns C = A @ B.T as torch.Tensor of shape (M, N), dtype=torch.float16
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float16 and B.dtype == torch.float16
        M, K = A.shape
        N, K2 = B.shape
        assert K == K2

        # Allocate output tensor
        C = torch.empty((M, N), dtype=torch.float16, device=A.device)

        # Launch configuration (16x16 threads per block)
        block = (16, 16, 1)
        grid = ((N + block[0] - 1) // block[0],
                (M + block[1] - 1) // block[1],
                1)

        # Argument list for the PTX kernel
        args = [
            A.data_ptr(),
            B.data_ptr(),
            C.data_ptr(),
            M,
            N,
            K
        ]

        # Launch the kernel via the harness
        ptx_launch(self.module, "mm_kernel", grid, block, args)

        return C
